import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";

import { normalizeGeneratedLoader } from "./generated-loader-normalization.mjs";

const root = new URL("../", import.meta.url);
const generatedTypecheckOptOut =
  "// @ts-nocheck -- generated by @napi-rs/cli";
const runtimePackages = [
  "@emnapi/core",
  "@emnapi/runtime",
  "@napi-rs/wasm-runtime",
];
const read = (path) =>
  readFileSync(new URL(path, root), "utf8");

const extractFunction = (source, name) => {
  const start = source.indexOf(`function ${name}(`);
  if (start < 0) throw new Error(`${name} not found`);
  const body = source.indexOf("{", start);
  let depth = 0;
  for (let index = body; index < source.length; index++) {
    if (source[index] === "{") depth++;
    if (source[index] !== "}") continue;
    depth--;
    if (depth === 0) return source.slice(start, index + 1);
  }
  throw new Error(`${name} is incomplete`);
};

describe("generated loader normalization", () => {
  test("keeps the generated typecheck opt-out while removing other directives", () => {
    const source = `/* eslint-disable */
// @ts-nocheck -- generated by @napi-rs/cli
// prettier-disable generated output
const binding = load()
`;
    expect(
      normalizeGeneratedLoader(source, {
        keepGeneratedTypecheckOptOut: true,
      }),
    ).toBe(`${generatedTypecheckOptOut}
const binding = load()
`);
  });

  for (const fileName of [
    "aho-corasick.wasi-browser.js",
    "aho-corasick.wasi.cjs",
  ]) {
    test(`${fileName} retries live cleanup after scheduling throws`, async () => {
      const source = read(fileName);
      expect(source).toContain(generatedTypecheckOptOut);
      const yieldTurn = extractFunction(
        source,
        "__yieldWasmRuntimePollTurn",
      );
      const prepare = extractFunction(
        source,
        "__prepareWasmEnvCleanupWithTurns",
      );
      // oxlint-disable-next-line typescript/no-implied-eval -- Executes functions extracted from the real generated loader.
      const createHarness = Function(`${yieldTurn}
${prepare}
let __emnapiWasmEnvCleanupPrepared = false
let __emnapiWasmEnvCleanupPreparing = false
let __emnapiWasmEnvCleanupRan = false
let __emnapiWasmEnvCleanupYielding = false
let __finishParkedWasmEnvCleanup
let workIsPending = true
let schedulerThrows = true
let finishCount = 0
const __WASM_RUNTIME_WORK_POLL_INTERVAL_MS = 0
const __WASM_RUNTIME_WORK_POLL_TRUSTED_ARRIVALS = 2
const __napiInstance = { exports: {
  napi_prepare_wasm_env_cleanup_begin: () => true,
  napi_prepare_wasm_env_cleanup_finish: () => { finishCount++ },
  napi_wasm_runtime_work_pending: () => workIsPending,
} }
const __createWasmRuntimePollPace = () => ({ arrivals: 0 })
const __armWasmRuntimePollStallBackup = () => {}
const __scheduleTimer = () => {}
const __prepareWasmEnvCleanup = () => {}
const __abortWasiDisposalIfThreadCrashed = () => {}
const __scheduleMacrotask = (callback) => {
  callback()
  if (schedulerThrows) throw new Error("scheduling failed")
}
return {
  prepare: __prepareWasmEnvCleanupWithTurns,
  recover: () => { schedulerThrows = false; workIsPending = false },
  state: () => ({ finishCount, preparing: __emnapiWasmEnvCleanupPreparing,
    parked: __finishParkedWasmEnvCleanup, workIsPending }),
}`);
      const harness = createHarness();

      // oxlint-disable-next-line typescript/await-thenable, typescript/no-confusing-void-expression -- Function-created fixture types are opaque to the type-aware linter.
      await expect(harness.prepare()).rejects.toThrow(
        "scheduling failed",
      );
      expect(harness.state()).toMatchObject({
        finishCount: 0,
        preparing: false,
        workIsPending: true,
      });
      expect(harness.state().parked).toBeFunction();

      harness.recover();
      await harness.prepare();
      expect(harness.state()).toEqual({
        finishCount: 1,
        preparing: false,
        parked: undefined,
        workIsPending: false,
      });
    });
  }

  test("published WASM runtime versions match the build manifest", () => {
    const rootManifest = JSON.parse(read("package.json"));
    const wasmManifest = JSON.parse(
      read("wasm/package.json"),
    );
    for (const packageName of runtimePackages) {
      expect(wasmManifest.dependencies[packageName]).toBe(
        rootManifest.devDependencies[packageName],
      );
    }
  });
});
